#include <vector>
#include <algorithm>
#include <cstdlib>

class Solution {
public:
    std::vector<int> countOfPairs(int n, int x, int y) {
        std::vector<int> ans(n, 0);
        for (int i = 1; i <= n; ++i) {
            for (int j = i + 1; j <= n; ++j) {
                int d = std::min({j - i, std::abs(i - x) + 1 + std::abs(j - y), std::abs(i - y) + 1 + std::abs(j - x)});
                ans[d - 1] += 2;
            }
        }
        return ans;
    }
};

class Solution {
    public int[] countOfPairs(int n, int x, int y) {
        int[] ans = new int[n];
        for (int i = 1; i <= n; ++i) {
            for (int j = i + 1; j <= n; ++j) {
                int d = Math.min(j - i, Math.min(Math.abs(i - x) + 1 + Math.abs(j - y), Math.abs(i - y) + 1 + Math.abs(j - x)));
                ans[d - 1] += 2;
            }
        }
        return ans;
    }
}

